\caption{\textsf{Boosted-}$\mathsf{Constrained\text{-}Regression}${}}
        \begin{algorithmic}[1]
        \Procedure{{\rm \textsf{Boosted-}}$\mathsf{Constrained\text{-}Regression}${}}{$\zeta,\delta,\sigma,q,\alpha,k$}
            \State Initialize variable $i=1$

            \vspace{2mm}

            \State\textit{\#~~Subroutine A (Obtain Samples)}
                \State Obtain sets $P$ and $U$ of $\wt{\Omega}\inparen{
                    \inparen{\nfrac{1}{\zeta^2}}\cdot
                        \inparen{d^k+\log{\nfrac{1}{\delta}}}
                }$ positive and unlabeled samples \label[step]{step:constReg:getSamples} 
                \item[]\quad~ respectively from the PIU learning model (\cref{prob:PUlearning}) 
                \vspace{4mm}
            \State \textit{\#~~Subroutine B (Solve Constrained Regression)}
            \State Find the optimal solution $p_i(\cdot)$ of the following program for $\rho=\frac{2}{\alpha\sigma} \cdot \zeta^{1/(2q)}$ \label[step]{step:constReg:findP} 
            \changetag{Constrained Regression) \ (#1}
            \[
                \min_{{\rm deg}(p)\leq k} \frac{\sum_{x\in U} \abs{{p(x)}}}{\abs{U}}
                \,,~~
                \text{s.t.}\,,~~
                \frac{\sum_{x\in P} \min\inbrace{p(x), 1}}{\abs{P}}     \geq 1  -  \rho
                \,.
                \addtocounter{equation}{1}\tag{\theequation}\label[program]{eq:constReg:prog}
            \]
            \changetag{#1}
            \State \textit{\#~~This program can be solved by formulating it as a linear program over monomials of degree at}
            \State \textit{\#~~most $k$ and using any polynomial-time linear program solver (see \cref{sec:module:linearProgram} for details)}
            \State Let $H_i=\mathds{1}\sinbrace{p_i(\cdot)\geq t_i}$ where $0\leq t_i\leq 1-\sqrt{\rho}$ is chosen to minimize $\sum_{x\in U}  \mathds{1}\sinbrace{p_i(x)\geq t_i}$\label[step]{step:constReg:selectThreshold}  
            \vspace{4mm}
            \State \textit{\#~~Subroutine C (Boost Performance)}
            \State Repeat the Subroutines A and B for $T=O\sinparen{\inparen{\nfrac{1}{\sqrt{\zeta}}}\cdot \log{\nfrac{1}{\delta}}}$ times to get $H_1,H_2,\dots,H_T$ 
            \State Select fresh sets $P'$ and $U'$ of $\wt{O}\sinparen{\inparen{\nfrac{1}{\zeta}}\cdot \log{\nfrac{1}{\delta}}}$ samples from the PIU model (\cref{prob:PUlearning})\label[step]{step:constReg:freshSamples}
            \State \textbf{return} $H_i$ that minimizes $\abs{H_i\cap U'}$ among $1\leq i\leq T$ 
        \EndProcedure
