There is a subset $\Theta$ of the natural parameter space and $\Lambda\geq \lambda > 0$ and $\eta>0$ such that:
        \begin{enumerate}
            \item \textbf{(Interiority)}           
                $\theta^\star$ is in the $\eta$-relative-interior $\Theta(\eta)$ of $\Theta$. \item \textbf{(Projection Oracle)} There is an efficient projection oracle to the $\eta$-relative-interior of $\Theta$. \item \textbf{(Bounded Fisher-Information)} For any $\theta\in \Theta$, $\lambda I \preceq \ensuremath{\operatornamewithlimits{\rm Cov}}_{x\sim \customcal{E}(\theta)}[t(x)]\preceq \Lambda I$.
            \item \textit{\textbf{(Starting Point)} There is an algorithm to find $\theta_0\in \Theta(\eta)$, s.t., $\relax{\theta^\star-\theta_0}\leq \mathrm{poly}(\nfrac{1}{\alpha})$ efficiently.} \end{enumerate}

\textit{\textbf{($\chi^2$-Bridge)} For each $\theta_1,\theta_2\in \Theta$ there is a $\theta$, s.t., $\chidiv{\customcal{E}(\theta_1)}{\customcal{E}(\theta)}, 
            \chidiv{\customcal{E}(\theta_2)}{\customcal{E}(\theta)}
            \leq  
            e^{\mathrm{poly}\inparen{\sfrac{\Lambda}{\lambda}}}$.}

This naturally defines the following concept classes.
    \begin{itemize}
        \item The family of \textit{decision trees of depth at most $t$} over $d$ variables; 
        \item The family of \textit{decision trees of size at most $s$} over $d$ variables.
    \end{itemize}

This naturally gives rise to the following concept class
    \begin{itemize}
        \item The family of \textit{decision trees of halfspaces of size at most $s$ and depth at most $t$} over $d$ variables. 
    \end{itemize}

\caption{\textsf{L1-Regression}{} \cite{kalai2008agnostically}}
        \begin{algorithmic}[1]
        \Procedure{{\rm\textsf{L1-Regression}{}}}{$\varepsilon,\delta,k$}
                \vspace{2mm}
                \State \textit{\#~~Construct Samples}
                    \State Let $n=\wt{\Omega}\inparen{\sfrac{\inparen{d^k+\log\inparen{\nfrac{1}{\delta}}}}{\varepsilon}}$ 
                    \State Draw $n$ samples $D=\inparen{(x_i,y_i)}_i$ from $\customcal{D}$
                    \vspace{2mm}
                \State \textit{\#~~Solve Regression}
                \State Find a polynomial $p$ of degree at most $k$ which minimizes $\inparen{\nfrac{1}{n}}\sum_{i}\abs{y_i-p(x_i)}$.
                \State \textit{\#~~This can be done by expanding all examples to monomials of degree at most $d$ and then}
                \State \textit{\#~~performing $L_1$-linear-regression using any polynomial time LP-solver.}
                \State  $H=\inbrace{x\colon p(x)\geq t}$ where $0\leq t\leq 1$ minimizes the error of the hypothesis on $D$
                \vspace{2mm}
                \State \textit{\#~~Boost Performance}
                \State Repeat the above steps $T=O\inparen{\inparen{\nfrac{1}{\varepsilon}}\log\inparen{\nfrac{1}{\delta}}}$ times to get $H_1,H_2,\dots,H_T$
                \State Evaluate $H_1,H_2,\dots,H_T$ on a fresh set of $O\inparen{\inparen{\nfrac{1}{\varepsilon^2}}\log\inparen{\nfrac{1}{\delta}}}$ samples
                \State \textbf{return} the best-performing hypothesis on $D$
            \EndProcedure
        \end{algorithmic}

