                                        \customcal{E}(x; \theta_2)
                                    }
                                }^{w}
                            }
                            &=
                            \int  e^{{w}(\theta_1-\theta_2)^\top t(x) + ({w}-1)A(\theta_2)-{w}A(\theta_1)} \customcal{E}(x; \theta_2){\rm d} x\\
                            &=
                            \int  e^{
                                    ({w}-1)A(\theta_2)+ A\inparen{\theta_1+({w}-1)(\theta_1 - \theta_2)} - {w}A(\theta_1) 
                                }
                             \,.
                        \end{align*}
                        Since $\theta_1$ is in the $\eta$-relative interior of $\Theta$ and $\theta_1-\theta_2$ lies in the affine subspace of $\Theta$ with $\relax{\theta_1-\theta_2}\leq R$, for the chosen ${w}$, $\theta_1+({w}-1)(\theta_1 - \theta_2)\in \Theta$.
                        Since $A$ is a $\Lambda$-smooth function over $\Theta$, 
                        \[
                            ({w}-1)A(\theta_2)+ A\inparen{\theta_1+({w}-1)(\theta_1 - \theta_2)} - {w}A(\theta_1) \leq \Lambda \relax{\theta_1-\theta_2}_2^2
                            + \Lambda({w}-1)^2\relax{\theta_1-\theta_2}_2^2\,.
                        \]
                        Using that $\relax{\theta_1-\theta_2}_2\leq R$, it follows that
                        \[
                            \operatornamewithlimits{\mathbb{E}}_{x\sim \customcal{E}(\theta_2)}\insquare{
                            \inparen{
                                \frac{
                                    \customcal{E}(x; \theta_1)
                                }{
                                    \customcal{E}(x; \theta_2)
                                }
                                }^{w}
                            }
                            \leq 
                            \exp\inparen{
                                \Lambda ({w}R)^2
                            }
                            \,.
                        \]
                    \end{proof}

